    if (Math.abs((offc + sp.off) - px) < sp.w * 0.45) { S.speed = MAX_SPEED / 6; S.shake = 6; S.pos = pSeg.p1.world.z - PLAYER_Z; break; }
  }
}
// машины на дороге
for (const c of cars) {
  const oldSeg = Math.floor(c.z / SEG);
  c.z += c.speed * dt;
  const ns = Math.floor(c.z / SEG);
  if (!segs[ns] || segs[ns].fork) { const a = segs[oldSeg] ? segs[oldSeg].cars : null; if (a && a.includes(c)) a.splice(a.indexOf(c), 1); c.dead = true; continue; }
  if (ns !== oldSeg && segs[oldSeg] && segs[ns]) {
    const a = segs[oldSeg].cars; a.splice(a.indexOf(c), 1); segs[ns].cars.push(c);
  }
  if (ns === pIdx && S.speed > c.speed && Math.abs(S.x - c.off) < 0.75) {
    S.speed = c.speed * 0.6; S.shake = 8; S.pos = c.z - PLAYER_Z - SEG * 0.8;
  }
  if (!c.passed && c.z < S.pos + PLAYER_Z - SEG) { c.passed = true; S.overtakes++; }
}

  // развилка: выбор по стороне, где едет машина
  if (pSeg.fork && !S.choice && pSeg.fork.i > 70) {
    const side = S.x < 0 ? -1 : 1;
    const dest = side < 0 ? pSeg.fork.left : pSeg.fork.right;
    S.choice = { side, i: pSeg.fork.i, dest };
    S.x = S.x - side * forkOffset(pSeg, side);
    buildStage(dest, pSeg.biome, dest === 'sea', pSeg.ox + side * FORK_D);
    sweepCars();
    forkHint.classList.remove('on');
  }
  if (S.choice && !pSeg.fork) S.choice = null;

  // подсказка перед развилкой
  const st = stages.find(s => pIdx >= s.start && pIdx < s.end);
  if (st && st.forkStart && S.mode === 'play') {
    const toFork = st.forkStart - pIdx;
    if (toFork < 170 && toFork > -60 && !S.choice) {
      forkHint.innerHTML = `← ${shortName(st.left)} · ${shortName(st.right)} →<small>держитесь левой или правой дороги</small>`;
      forkHint.classList.add('on');
    }
  }
  // финиш; на заставке у моря — начинаем поездку заново
  if (st && st.final && pIdx > st.finishIndex && S.mode === 'play') finishRide();
  if (st && st.final && S.mode === 'intro' && pIdx > st.finishIndex - 120) { reset(); S.speed = MAX_SPEED * 0.6; }
}

